// main/portal.c
#include "portal.h"
#include "esp_http_server.h"
#include "esp_log.h"
#include "esp_system.h"
#include "lwip/sockets.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include <string.h>
#include <stdlib.h>

static const char *TAG = "portal";

// Embedded HTML generated by CMake EMBED_TXTFILES
extern const char webpage_html_start[] asm("_binary_webpage_html_start");
extern const char webpage_html_end[]   asm("_binary_webpage_html_end");

static httpd_handle_t  s_server      = NULL;
static TaskHandle_t    s_dns_task    = NULL;
static volatile bool   s_dns_running = false;

// --- HTTP handlers ----------------------------------------------------------
static esp_err_t root_get_handler(httpd_req_t *req)
{
    size_t len = (size_t)(webpage_html_end - webpage_html_start);
    httpd_resp_set_type(req, "text/html");
    httpd_resp_send(req, webpage_html_start, len);
    return ESP_OK;
}

static esp_err_t redirect_handler(httpd_req_t *req)
{
    httpd_resp_set_status(req, "302 Found");
    httpd_resp_set_hdr(req, "Location", "/");
    httpd_resp_send(req, NULL, 0);
    return ESP_OK;
}

static esp_err_t login_post_handler(httpd_req_t *req)
{
    // Drain the request body so the connection can be cleanly reused,
    // but discard credentials — USB forwarding removed (C5 has no
    // USB device controller).
    char body[512];
    int total = req->content_len;
    if (total > 0 && total < (int)sizeof(body)) {
        int received = 0;
        while (received < total) {
            int r = httpd_req_recv(req, body + received, total - received);
            if (r <= 0) break;
            received += r;
        }
    }

    httpd_resp_set_status(req, "302 Found");
    httpd_resp_set_hdr(req, "Location", "/");
    httpd_resp_send(req, NULL, 0);
    return ESP_OK;
}

// --- DNS hijack -------------------------------------------------------------
static void dns_task(void *arg)
{
    (void)arg;
    int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock < 0) goto done;

    struct sockaddr_in addr = { 0 };
    addr.sin_family      = AF_INET;
    addr.sin_port        = htons(53);
    addr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        goto done;
    }

    uint8_t buf[512];
    uint8_t resp[512];

    while (s_dns_running) {
        struct sockaddr_in from;
        socklen_t fromlen = sizeof(from);
        int len = recvfrom(sock, buf, sizeof(buf), 0,
                           (struct sockaddr *)&from, &fromlen);
        if (len < 12) continue;

        uint16_t qdcount = (buf[4] << 8) | buf[5];
        if (qdcount != 1) continue;

        // Walk question section
        int qend = 12;
        while (qend < len && buf[qend] != 0) {
            if ((buf[qend] & 0xC0) == 0xC0) { qend += 2; goto have_question; }
            qend += 1 + buf[qend];
        }
        if (qend < len && buf[qend] == 0) qend++;
    have_question:
        qend += 4;
        if (qend > len) continue;

        memcpy(resp, buf, qend);

        resp[2] = 0x81;
        resp[3] = 0x80;
        resp[6] = 0; resp[7] = 1;
        resp[8] = 0; resp[9] = 0;
        resp[10] = 0; resp[11] = 0;

        int rp = qend;
        resp[rp++] = 0xC0; resp[rp++] = 0x0C;
        resp[rp++] = 0x00; resp[rp++] = 0x01;
        resp[rp++] = 0x00; resp[rp++] = 0x01;
        resp[rp++] = 0x00; resp[rp++] = 0x00;
        resp[rp++] = 0x00; resp[rp++] = 0x3C;
        resp[rp++] = 0x00; resp[rp++] = 0x04;
        resp[rp++] = 192; resp[rp++] = 168;
        resp[rp++] = 4;   resp[rp++] = 1;

        sendto(sock, resp, rp, 0, (struct sockaddr *)&from, fromlen);
    }

    close(sock);
done:
    s_dns_task = NULL;
    vTaskDelete(NULL);
}

// --- public API -------------------------------------------------------------
esp_err_t portal_init(void)
{
    return ESP_OK;
}

esp_err_t portal_start(void)
{
    if (s_server) return ESP_OK;

    httpd_config_t config = HTTPD_DEFAULT_CONFIG();
    config.server_port     = 80;
    config.max_uri_handlers = 16;
    config.lru_purge_enable = true;
    config.stack_size      = 4096;

    if (httpd_start(&s_server, &config) != ESP_OK) {
        s_server = NULL;
        return ESP_FAIL;
    }

    static const httpd_uri_t uri_root = {
        .uri = "/", .method = HTTP_GET, .handler = root_get_handler
    };
    static const httpd_uri_t uri_login = {
        .uri = "/login", .method = HTTP_POST, .handler = login_post_handler
    };
    static const httpd_uri_t uri_204 = {
        .uri = "/generate_204", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_gen_204 = {
        .uri = "/gen_204", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_apple = {
        .uri = "/hotspot-detect.html", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_apple_legacy = {
        .uri = "/library/test/success.html", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_win = {
        .uri = "/connecttest.txt", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_ncsi = {
        .uri = "/ncsi.txt", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_success = {
        .uri = "/success.txt", .method = HTTP_GET, .handler = redirect_handler
    };
    static const httpd_uri_t uri_redirect = {
        .uri = "/redirect", .method = HTTP_GET, .handler = redirect_handler
    };

    httpd_register_uri_handler(s_server, &uri_root);
    httpd_register_uri_handler(s_server, &uri_login);
    httpd_register_uri_handler(s_server, &uri_204);
    httpd_register_uri_handler(s_server, &uri_gen_204);
    httpd_register_uri_handler(s_server, &uri_apple);
    httpd_register_uri_handler(s_server, &uri_apple_legacy);
    httpd_register_uri_handler(s_server, &uri_win);
    httpd_register_uri_handler(s_server, &uri_ncsi);
    httpd_register_uri_handler(s_server, &uri_success);
    httpd_register_uri_handler(s_server, &uri_redirect);

    s_dns_running = true;
    xTaskCreate(dns_task, "dns_hijack", 4096, NULL, 4, &s_dns_task);

    return ESP_OK;
}

esp_err_t portal_stop(void)
{
    if (s_dns_running) {
        s_dns_running = false;
        for (int i = 0; i < 10 && s_dns_task != NULL; i++) {
            vTaskDelay(pdMS_TO_TICKS(50));
        }
    }
    if (s_server) {
        httpd_stop(s_server);
        s_server = NULL;
    }
    return ESP_OK;
}

bool portal_is_running(void) { return s_server != NULL; }